content.css:
.icd-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: 'Segoe UI', wf_segoe-ui_normal, helvetica, arial, sans-serif;
}
.icd-root svg {
  display: block;
}
.icd-root g.icd-cat:hover {
  opacity: 0.8;
}
.icd-root g.icd-cat:focus {
  outline: 2px solid #005FB8;
  outline-offset: 1px;
}
.icd-root g.icd-cat:focus:not(:focus-visible) {
  outline: none;
}
